from taf.rfrl.procedures.resources.python.logger import log_input_and_output, log_env_state, log_to_console
from taf.rfrl.procedures.resources.python.testline.TestLine import TestLine
from taf.rfrl.procedures.resources.python.sw_stream.interface import get_sw_stream
from taf.rfrl.procedures.resources.python.status_check.status_selector.statuses import \
    STATUSES, AVAILABILITY_STATUS, OPERATIONAL_STATE, ADMINISTRATIVE_STATE
from taf.rfrl.procedures.resources.python.status_check.status_selector.exceptions import \
    ImpossibleStatusSelection


class StatusSelector:
    """ Responsible for matching appropriate status with SW version currently uploaded on BTS. """

    def __init__(self):
        self._sw_stream = None
        self._testline = TestLine()

    @property
    def sw_stream(self):
        """
        Returns current SW stream read from BTS.
        :rtype: str
        """
        if not self._sw_stream:
            self._sw_stream = get_sw_stream(device=self._testline.get_type_of_setup())
        return self._sw_stream

    @log_input_and_output
    def select_availability_status(self, variant, is_iot=False, sharing_rmods_state=None):
        """
        Returns availabilityStatus appropriate for current SW stream on BTS.
        :param variant: specifies which variant of availabilityStatus should be matched with SW stream;
                        one of following values: 'online', 'offline', 'not_installed', 'degraded', 'dependency',
                        'failed'
        :type variant: str
        :param is_iot: info whether given cell is of NB-IoT technology; defaults to False (non-IoT cell or not
                       a cell at all)
        :type is_iot: bool
        :param sharing_rmods_state: info on state of sharing RMODs if cell is shared between more than one RMOD
        :type sharing_rmods_state: None or str; defaults to None - cell is not shared or the object we want
                      to select availability status for is not a cell at all
        :return: availabilityStatus appropriate for current SW stream, i.e.
                 for variant: 'not_installed' and SW stream: 'SBTS22R1' returned value would be: 'NotInstalled'
        :rtype: str
        :raises ImpossibleStatusSelection: when availabilityStatus for provided variant and
                                           current SW stream on BTS can't be found
        """
        return self._select_avaliability_status(variant, is_iot, sharing_rmods_state)

    @log_input_and_output
    def select_operational_state(self, variant, sharing_rmods_state=None):
        """
        Returns operationalState appropriate for current SW stream on BTS.
        :param variant: specifies which variant of operationalState should be matched with SW stream;
                        one of following values: 'enabled', 'disabled'
        :type variant: str
        :return: operationalState appropriate for current SW stream, i.e.
                 for variant: 'disabled' and SW stream: 'SBTS22R1' returned value would be: 'Disabled'
        :rtype: str
        :param sharing_rmods_state: info on state of sharing RMODs if cell is shared between more than one RMOD
        :type sharing_rmods_state: None or str; defaults to None - cell is not shared or the object we want
                      to select availability status for is not a cell at all
        :raises ImpossibleStatusSelection: when operationalState for provided variant and
                                           current SW stream on BTS can't be found
        """
        return self._select_status(OPERATIONAL_STATE, variant, sharing_rmods_state)

    @log_input_and_output
    def select_administrative_state(self, variant):
        """
        Returns administrativeState appropriate for current SW stream on BTS.
        :param variant: specifies which variant of administrativeState should be matched with SW stream;
                        one of following values: 'unlocked', 'locked'
        :type variant: str
        :return: administrativeState appropriate for current SW stream, i.e.
                 for variant: 'unlocked' and SW stream: 'SBTS22R1' returned value would be: 'Unlocked'
        :rtype: str
        :raises ImpossibleStatusSelection: when administrativeState for provided variant and
                                           current SW stream on BTS can't be found
        """
        return self._select_status(ADMINISTRATIVE_STATE, variant)

    @staticmethod
    @log_input_and_output
    def translate_status_for_webui(status):
        """
        Translates statuses that are equal to None to "-" for selenium.
        :param status: status to be translated
        :type status: Union[str, None]
        :return: translated status
        :rtype: str
        """
        return '-' if status is None else status

    @log_input_and_output
    def _select_status(self, name, variant, sharing_rmods_state=None):
        """
        Returns status selected for given name and variant and current SW stream on BTS.
        :param name: name of status which will be used during selection;
                     one of following vales: 'operational_state', 'administrative_state'
        :type name: str
        :param variant: variant of specified status name which will be used during selection, i.e.
                        'enabled' or 'disabled' for 'operational_state'
        :type variant: str
        :param sharing_rmods_state: (valid only for cells) info on state of sharing RMODs if cell is shared
                      between more than one RMOD
        :type sharing_rmods_state: None or str; defaults to None - cell is not shared or the object we want
                      to select availability status for is not a cell at all
        :return: status appropriate for given name and variant and for current SW stream on BTS
        :rtype: str
        :raises ImpossibleStatusSelection: when status for provided name, variant and current SW stream on BTS
                                           cannot be found in available STATUSES
        """
        log_env_state('SW stream on BTS is {}'.format(self.sw_stream))

        if sharing_rmods_state and name == "operational_state":
            variant = self._change_operational_state_variant_for_shared_cell(sharing_rmods_state=sharing_rmods_state)

        try:
            return STATUSES[name][variant][self.sw_stream]
        except KeyError:
            raise ImpossibleStatusSelection(
                "Status for name: '{}', variant: '{}' and SW stream: '{}' is not defined in available STATUSES".format(
                    name, variant, self.sw_stream))

    @log_input_and_output
    def _select_avaliability_status(self, variant, is_iot=False, sharing_rmods_state=None):
        """
        Returns availability status selected for given name and variant and current SW stream on BTS.
        :param variant: variant of specified status name which will be used during selection;
                        one of following values: 'online', 'offline', 'not_installed', 'degraded', 'dependency',
                        'failed'
        :type variant: str
        :param is_iot: info whether given cell is of NB-IoT technology
        :type is_iot: bool
        :param sharing_rmods_state: info on state of sharing RMODs if cell is shared between more than one RMOD
        :type sharing_rmods_state: None or str; defaults to None - cell is not shared or the object we want
                      to select availability status for is not a cell at all
        :return: status appropriate for given name and variant and for current SW stream on BTS
        :rtype: str
        :raises ImpossibleStatusSelection: when status for provided name, variant and current SW stream on BTS
                                           cannot be found in available STATUSES
        """
        log_env_state('SW stream on BTS is {}'.format(self.sw_stream))

        if sharing_rmods_state:
            variant = self._change_avaliability_status_variant_for_shared_cell(sharing_rmods_state=sharing_rmods_state,
                                                                               variant=variant)
        try:
            if is_iot:
                return STATUSES[AVAILABILITY_STATUS][variant][self.sw_stream]['iot']

            return STATUSES[AVAILABILITY_STATUS][variant][self.sw_stream]['not_iot']

        except KeyError:
            raise ImpossibleStatusSelection(
                "Status for name: '{}', variant: '{}', SW stream: '{}' and IoT: {} is not defined in available "
                "STATUSES".format(AVAILABILITY_STATUS, variant, self.sw_stream, is_iot))

    def _change_avaliability_status_variant_for_shared_cell(self, sharing_rmods_state, variant):
        if variant == "dependency" or variant == "failed":
            if sharing_rmods_state in ("partially_locked", "unlocked", "partially_disabled"):
                log_to_console("Cell is shared between more than one RMOD and those RMODs are {}. "
                               "Changing desired status variant to: degraded".format(sharing_rmods_state))
                return "degraded"

        if variant == "online" and sharing_rmods_state in ("partially_locked", "partially_disabled"):
            log_to_console("Cell is shared between more than one RMOD and those RMODs are {}. "
                           "Changing desired status variant to: degraded".format(sharing_rmods_state))
            return "degraded"

        return variant

    def _change_operational_state_variant_for_shared_cell(self, sharing_rmods_state):
        if sharing_rmods_state in ("partially_locked", "unlocked", "partially_disabled"):
            log_to_console("Cell is shared between more than one RMOD and those RMODs are {}. "
                           "Changing desired status variant to: enabled".format(sharing_rmods_state))
            return "enabled"

        if sharing_rmods_state in ("disabled", "locked"):
            log_to_console("Cell is shared between more than one RMOD and all of those RMODs are {}. "
                           "Changing desired status variant to: disabled".format(sharing_rmods_state))
            return "disabled"
